CREATE TABLE public.bell_push_deliveries (event_key text NOT NULL, user_id uuid NOT NULL, delivered_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_key,user_id));
GRANT ALL ON public.bell_push_deliveries TO service_role;
ALTER TABLE public.bell_push_deliveries ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.bell_role_can(_company uuid,_role public.app_role,_module text) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT _role='superuser' OR coalesce((SELECT enabled FROM public.role_permissions WHERE company_id=_company AND role=_role AND module=_module),CASE WHEN _role='admin' THEN _module IN ('pending_works','leave_approvals','approvals') WHEN _role='supervisor' THEN _module IN ('pending_works','leave_approvals','approvals') ELSE false END); $$;
CREATE FUNCTION public.pending_bell_push() RETURNS TABLE(event_key text,user_id uuid,title text,url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH recipients AS (SELECT r.* FROM public.user_roles r WHERE r.registration_status='active' AND public.member_is_active(r.user_id)), events AS (
SELECT 'swap-request:'||s.id||':'||coalesce(s.snoozed_until::text,'initial') key,r.user_id,'On-call swap request' title,'/standby?swap='||s.id url FROM public.standby_swaps s JOIN recipients r ON r.company_id=s.company_id AND r.user_id=s.target_id WHERE s.status='pending' AND (s.snoozed_until IS NULL OR s.snoozed_until<=now()) AND public.company_module_access(s.company_id,'standby')
UNION ALL SELECT 'swap-approval:'||s.id,r.user_id,'On-call swap needs approval','/standby?swap='||s.id FROM public.standby_swaps s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin','supervisor') WHERE s.status='accepted' AND NOT s.manager_approved AND public.company_module_access(s.company_id,'standby')
UNION ALL SELECT 'leave-consult:'||s.id,r.user_id,'Leave consultation awaiting response','/admin/leave?request='||s.id FROM public.leave_requests s JOIN recipients r ON r.company_id=s.company_id AND r.user_id=s.consulted_supervisor_id WHERE s.status='pending' AND s.supervisor_response IS NULL AND public.bell_role_can(r.company_id,r.role,'leave_approvals')
UNION ALL SELECT 'leave-review:'||s.id,r.user_id,'Leave request awaiting office review','/admin/leave?request='||s.id FROM public.leave_requests s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin') WHERE s.status='pending' AND (s.supervisor_response IS NOT NULL OR s.consulted_supervisor_id IS NULL) AND public.bell_role_can(r.company_id,r.role,'leave_approvals')
UNION ALL SELECT 'equipment-report:'||s.id,r.user_id,'New equipment problem report','/admin/jobs?new=true&assetId='||s.asset_id||'&problemId='||s.id FROM public.equipment_problem_reports s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin','supervisor') WHERE s.status='open' AND public.bell_role_can(r.company_id,r.role,'pending_works')
UNION ALL SELECT 'store-report:'||s.id,r.user_id,'New site or fabric problem report','/admin/jobs?view=pending#store-report-'||s.id FROM public.store_problem_reports s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin','supervisor') WHERE s.status='open' AND public.bell_role_can(r.company_id,r.role,'pending_works')
UNION ALL SELECT 'expense-category:'||s.id,r.user_id,'Expense category needs approval','/admin/approvals?category=expenses&item='||s.id FROM public.expense_categories s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin','supervisor') WHERE s.status='pending' AND public.company_module_access(s.company_id,'receipts')
UNION ALL SELECT 'passport:'||s.id,r.user_id,'Technical passport handover needs review','/equipment/'||s.asset_id||'?view=passport&submission='||s.id FROM public.passport_submissions s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin','supervisor') WHERE s.status='pending' AND public.company_module_access(s.company_id,'lift_pack')
UNION ALL SELECT 'survey:'||s.id,r.user_id,'Site visit awaiting review','/surveys?survey='||s.id FROM public.site_surveys s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin','supervisor') AND (s.reviewer_id IS NULL OR s.reviewer_id=r.user_id) WHERE s.status IN ('submitted','under_review') AND public.company_module_access(s.company_id,'site_surveys')
UNION ALL SELECT 'quote:'||s.id||':'||s.status,r.user_id,'Quote decision needs attention','/estimates?quote='||s.id FROM public.customer_quotes s JOIN recipients r ON r.company_id=s.company_id AND r.role IN ('superuser','admin','supervisor') WHERE (s.status='awaiting_confirmation' OR (s.status IN ('accepted','declined') AND s.office_seen_at IS NULL)) AND public.company_module_access(s.company_id,'core')
UNION ALL SELECT 'crm-followup:'||s.id||':'||s.due_at,r.user_id,'CRM follow-up is due','/crm?lead='||s.opportunity_id FROM public.crm_followups s JOIN recipients r ON r.company_id=s.company_id AND (s.assignee_id IS NULL OR s.assignee_id=r.user_id) WHERE s.done_at IS NULL AND s.due_at<=now() AND public.crm_rank(coalesce(r.crm_access,public.crm_default_level(r.role)))>=public.crm_rank('viewer') AND public.company_module_access(s.company_id,'crm_pipeline')
UNION ALL SELECT 'urgent-job:'||j.id||':'||j.scheduled_date,r.user_id,'Urgent dispatched job assigned to you','/dashboard#assigned-job-'||j.id FROM public.jobs j JOIN recipients r ON r.company_id=j.company_id AND (r.user_id=j.assigned_technician_id OR r.user_id=j.secondary_technician_id OR EXISTS(SELECT 1 FROM public.job_crew c WHERE c.job_id=j.id AND c.user_id=r.user_id)) WHERE j.priority='urgent' AND j.scheduled_date IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.job_sheets s WHERE s.job_id=j.id AND s.status='completed')
UNION ALL SELECT 'open-job:'||j.id||':'||j.scheduled_date,r.user_id,'Job up for grabs','/available-jobs?job='||j.id FROM public.jobs j JOIN recipients r ON r.company_id=j.company_id WHERE j.open_to_claim AND j.scheduled_date IS NOT NULL AND public.company_module_access(j.company_id,'skills_dispatch') AND public.is_dispatchable_member(r.user_id,j.company_id) AND EXISTS(SELECT 1 FROM public.shifts sh WHERE sh.company_id=j.company_id AND sh.user_id=r.user_id AND sh.ended_at IS NULL AND sh.shift_type IN ('shift','standby')) AND r.user_id IS DISTINCT FROM j.assigned_technician_id AND r.user_id IS DISTINCT FROM j.secondary_technician_id AND NOT EXISTS(SELECT 1 FROM public.job_crew c WHERE c.job_id=j.id AND c.user_id=r.user_id) AND NOT EXISTS(SELECT 1 FROM public.job_sheets s WHERE s.job_id=j.id AND s.status='completed') AND NOT EXISTS(SELECT 1 FROM public.job_skills k WHERE k.job_id=j.id AND k.mandatory AND NOT EXISTS(SELECT 1 FROM public.member_skills m WHERE m.user_id=r.user_id AND m.skill_id=k.skill_id))
) SELECT e.key,e.user_id,e.title,e.url FROM events e WHERE NOT EXISTS(SELECT 1 FROM public.bell_push_deliveries d WHERE d.event_key=e.key AND d.user_id=e.user_id) ORDER BY e.key,e.user_id LIMIT 100;
$$;
REVOKE ALL ON FUNCTION public.pending_bell_push() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pending_bell_push() TO service_role;
REVOKE ALL ON FUNCTION public.bell_role_can(uuid,public.app_role,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.bell_role_can(uuid,public.app_role,text) TO service_role;